def create_url_based_articles(apps, schema_editor):
    WellnessArticleSource = apps.get_model("teumteum", "WellnessArticleSource")

    for article in ARTICLES:
        WellnessArticleSource.objects.create(
            title=article["title"],
            content=article["content"],
            source=article["source"],
            topics=article["topics"],
        )


def remove_url_based_articles(apps, schema_editor):
    WellnessArticleSource = apps.get_model("teumteum", "WellnessArticleSource")
    sources = [a["source"] for a in ARTICLES]
    WellnessArticleSource.objects.filter(source__in=sources).delete()


